create extension if not exists pgcrypto;
create table if not exists profiles(id text primary key,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists agents(id uuid primary key default gen_random_uuid(),owner_id text not null references profiles(id) on delete cascade,slug text unique not null,name text not null,description text not null default '',strategy text not null,model text not null,website text,x_account text,github text,avatar_url text,starting_capital numeric(38,18) not null check(starting_capital>=0),verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists agent_wallets(id uuid primary key default gen_random_uuid(),agent_id uuid not null references agents on delete cascade,address text unique not null check(address ~ '^0x[0-9a-f]{40}$'),chain_id bigint not null default 4663,last_synced_block bigint,verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists wallet_verification_nonces(id uuid primary key,address text not null,nonce_hash text unique not null,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create table if not exists transactions(id uuid primary key default gen_random_uuid(),wallet_id uuid not null references agent_wallets on delete cascade,tx_hash text not null,block_number bigint not null,log_index integer not null default 0,event_type text not null,payload jsonb not null default '{}',block_timestamp timestamptz not null,created_at timestamptz not null default now(),unique(wallet_id,tx_hash,log_index,event_type));
create table if not exists normalized_trades(id uuid primary key default gen_random_uuid(),transaction_id uuid unique not null references transactions on delete cascade,agent_id uuid not null references agents on delete cascade,side text not null check(side in('buy','sell','swap')),asset_address text not null,symbol text not null,quantity numeric(78,18) not null,price_usd numeric(38,18),fee_usd numeric(38,18) not null default 0,traded_at timestamptz not null);
create table if not exists positions(id uuid primary key default gen_random_uuid(),agent_id uuid not null references agents on delete cascade,asset_address text not null,symbol text not null,quantity numeric(78,18) not null default 0,cost_basis_usd numeric(38,18) not null default 0,realized_pnl_usd numeric(38,18) not null default 0,updated_at timestamptz not null default now(),unique(agent_id,asset_address));
create table if not exists portfolio_snapshots(id uuid primary key default gen_random_uuid(),agent_id uuid not null references agents on delete cascade,equity_usd numeric(38,18) not null,realized_pnl_usd numeric(38,18) not null,unrealized_pnl_usd numeric(38,18) not null,captured_at timestamptz not null default now());
create table if not exists asset_prices(id uuid primary key default gen_random_uuid(),asset_address text not null,symbol text not null,price_usd numeric(38,18) not null,source text not null,observed_at timestamptz not null,unique(asset_address,source,observed_at));
create table if not exists stock_tokens(id uuid primary key default gen_random_uuid(),symbol text unique not null,asset_address text unique not null,reference_symbol text not null,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists agent_metrics(agent_id uuid primary key references agents on delete cascade,portfolio_value_usd numeric(38,18) not null default 0,realized_pnl_usd numeric(38,18) not null default 0,unrealized_pnl_usd numeric(38,18) not null default 0,roi numeric(20,8) not null default 0,pnl_24h numeric(38,18) not null default 0,win_rate numeric(10,6) not null default 0,trade_count bigint not null default 0,volume_usd numeric(38,18) not null default 0,updated_at timestamptz not null default now());
create table if not exists leaderboard_snapshots(id uuid primary key default gen_random_uuid(),agent_id uuid not null references agents on delete cascade,period text not null,rank integer not null,score numeric(38,18) not null,captured_at timestamptz not null default now());
create table if not exists battles(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null default '',starts_at timestamptz not null,ends_at timestamptz not null,starting_balance numeric(38,18) not null,allowed_assets text[],rules jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists battle_participants(battle_id uuid references battles on delete cascade,agent_id uuid references agents on delete cascade,primary key(battle_id,agent_id));
create table if not exists battle_snapshots(id uuid primary key default gen_random_uuid(),battle_id uuid not null references battles on delete cascade,agent_id uuid not null references agents on delete cascade,equity_usd numeric(38,18) not null,return_pct numeric(20,8) not null,captured_at timestamptz not null default now());
create table if not exists share_cards(id uuid primary key default gen_random_uuid(),agent_id uuid references agents on delete cascade,battle_id uuid references battles on delete cascade,kind text not null,payload jsonb not null,created_at timestamptz not null default now());
create table if not exists sync_state(key text primary key,value jsonb not null,updated_at timestamptz not null default now());
create index if not exists agents_verified_idx on agents(verified_at) where verified_at is not null;create index if not exists transactions_wallet_block_idx on transactions(wallet_id,block_number);create index if not exists trades_agent_time_idx on normalized_trades(agent_id,traded_at desc);create index if not exists snapshots_agent_time_idx on portfolio_snapshots(agent_id,captured_at desc);create index if not exists leaderboard_period_rank_idx on leaderboard_snapshots(period,rank,captured_at desc);create index if not exists battle_snapshots_idx on battle_snapshots(battle_id,captured_at desc);create index if not exists nonce_expiry_idx on wallet_verification_nonces(expires_at) where used_at is null;
